SELECT r.id, r.flow_id AS flowId, r.status, r.triggered_by AS triggeredBy, r.run_type AS runType, r.duration_ms AS durationMs, r.error_msg AS errorMsg, r.override_base_url AS overrideBaseUrl, r.start_time AS startTime, r.end_time AS endTime, r.suite_run_id AS suiteRunId, r.batch_id AS batchId, r.remark, r.create_by AS createBy, r.create_time AS createTime, f.name AS flowName FROM brick_flow_run r INNER JOIN brick_flow f ON r.flow_id = f.id WHERE f.swagger_mapping_id = #{swaggerMappingId} AND f.is_deleted = 0 AND f.name LIKE CONCAT('%', #{flowName}, '%') AND r.status = #{status} AND r.start_time >= #{startDate} AND r.start_time <= #{endDate} AND r.suite_run_id = #{testSuiteRunId} AND r.batch_id = #{batchId} AND r.run_type = #{runType}
GROUP BY r.flow_id
ORDER BY r.start_time DESC LIMIT #{offset}, #{limit}

SELECT

    COUNT(DISTINCT r.flow_id)
    COUNT(*)

FROM brick_flow_run r
INNER JOIN brick_flow f ON r.flow_id = f.id
WHERE f.swagger_mapping_id = #{swaggerMappingId} AND f.is_deleted = 0
AND f.name LIKE CONCAT('%', #{flowName}, '%')
AND r.status = #{status}
AND r.start_time >= #{startDate}
AND r.start_time <= #{endDate}
AND r.suite_run_id = #{testSuiteRunId}
AND r.batch_id = #{batchId}
AND r.run_type = #{runType}

SELECT COUNT(*)
FROM brick_flow_run
WHERE flow_id = #{flowId}
AND status = #{status}
AND start_time >= #{startDate}
AND start_time <= #{endDate}

